    (s : CoordSort) (a b : LinearExpr C n) (x : Fin n → Real) :
    evalLinear R s (a.add b) x = evalLinear R s a x + evalLinear R s b x

private theorem evalLinear_neg {C : RegionCode} {n : Nat} (R : Realization C)
